  useEffect(() => { if (compact || !profile) return; const previousTitle = document.title; const title = `${profile.displayName || profile.githubLogin || profile.slug} — GitHubFolio`; document.title = title; const description = profile.bio || `Explore ${profile.displayName || profile.slug}'s selected GitHub work.`; let meta = document.querySelector('meta[name="description"]'); if (!meta) { meta = document.createElement("meta"); meta.setAttribute("name", "description"); document.head.appendChild(meta); } meta.setAttribute("content", description); for (const property of ["og:title", "og:description"]) { let tag = document.querySelector(`meta[property="${property}"]`); if (!tag) { tag = document.createElement("meta"); tag.setAttribute("property", property); document.head.appendChild(tag); } tag.setAttribute("content", property === "og:title" ? title : description); } return () => { document.title = previousTitle; }; }, [compact, profile]);
